/* No requests or storage; inputs are never propagated in navigation. */
(function(){'use strict';
const byId=id=>document.getElementById(id),en=document.documentElement.lang==='en',t=(zh,english)=>en?english:zh;
const preset=byId('preset'),alpha=byId('alpha'),slider=byId('alpha-slider'),e0=byId('estimate-0'),e1=byId('estimate-1'),error=byId('input-error'),status=byId('calculation-status'),result=byId('result'),context=byId('fixture-context');
const fields=[alpha,e0,e1];
function pending(){result.hidden=true;error.textContent='';fields.forEach(f=>f.removeAttribute('aria-invalid'));status.textContent=t('输入尚未计算。点击“计算”生成当前结果。','Inputs have not been calculated. Select Calculate for current results.');}
function load(){const fixture=globalThis.ModelAtlasDiffusionFixtures[preset.value];pending();if(!fixture){error.textContent=t('预设无效，请重置。','Invalid preset. Reset to recover.');return;}alpha.value=String(fixture.alpha_bar);slider.value=alpha.value;e0.value=String(fixture.estimate[0]);e1.value=String(fixture.estimate[1]);context.textContent='x0 = '+JSON.stringify(fixture.x0)+'; epsilon = '+JSON.stringify(fixture.epsilon);}
function read(field,lo,hi,label){const raw=field.value.trim(),n=Number(raw);if(raw===''||!Number.isFinite(n)||n<lo||n>hi){field.setAttribute('aria-invalid','true');throw new Error(label+t('：请输入范围内的有限数值 [',': enter a finite number in [')+lo+', '+hi+'].');}return n;}
function format(v){return typeof v==='number'?(Math.abs(v)<1e-12?'0':Number(v.toFixed(9)).toString()):'['+v.map(format).join(', ')+']';}
function calculate(){pending();try{const f=globalThis.ModelAtlasDiffusionFixtures[preset.value];if(!f)throw new Error(t('预设无效，请重置。','Invalid preset. Reset to recover.'));const a=read(alpha,.01,1,'alpha_bar'),estimate=[read(e0,-10,10,'epsilon_hat[0]'),read(e1,-10,10,'epsilon_hat[1]')];const r=globalThis.ModelAtlasDiffusionNoise.calculate(a,f.x0,f.epsilon,estimate);slider.value=String(a);Object.keys(r).forEach(k=>{const el=byId('out-'+k);if(el)el.textContent=format(r[k]);});result.hidden=false;status.textContent=t('已计算当前输入；显示最多九位小数，中间运算不舍入。','Current inputs calculated; display rounds to nine decimals, intermediate arithmetic does not.');}catch(e){result.hidden=true;error.textContent=e.message;status.textContent=t('未生成结果。修正输入后重新计算，或重置。','No result produced. Correct inputs and calculate again, or reset.');}}
fields.forEach(f=>f.addEventListener('input',()=>{pending();if(f===alpha&&alpha.value.trim()!==''&&Number.isFinite(Number(alpha.value))&&Number(alpha.value)>=.01&&Number(alpha.value)<=1)slider.value=alpha.value;}));
slider.addEventListener('input',()=>{alpha.value=slider.value;pending();});preset.addEventListener('change',load);byId('calculate').addEventListener('click',calculate);byId('reset').addEventListener('click',()=>{preset.value='worked';load();});
const sections=['noise-main','contract','worked','interactive','run','transfer','reference','finish','downloads'];
function navigation(){const params=new URLSearchParams(location.search||''),candidate=params.getAll('region').length===1?params.get('region'):null,region=['unknown','CN','US','GB','SG','international'].includes(candidate)?candidate:'unknown';document.querySelectorAll('a[href]').forEach(link=>{const href=link.getAttribute('href')||'';if(/^(?:academy|diffusion-noise-lab|video-sampling-lab|tiny-training)(?:-en)?\.html(?:[?#]|$)/.test(href)){const [path,hash]=href.split('#'),current=(location.hash||'').slice(1),fragment=link.hasAttribute('data-noise-language')?(sections.includes(current)?current:''):hash;link.setAttribute('href',path.split('?')[0]+'?region='+region+(fragment?'#'+fragment:''));}});}
load();navigation();window.addEventListener('hashchange',navigation);window.addEventListener('popstate',navigation);
})();
